<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, auth, clearAuth } from '../api'
import type { Idea, Product, Session, SystemStatus, User } from '../types'
import { formatDate, ideaTitle, statusLabels, toast } from '../utils'
const router = useRouter(); const tab = ref('profile'); const nickname = ref(auth.user?.nickname || ''); const currentPassword = ref(''); const newPassword = ref(''); const revokeOnPassword = ref(true); const sessions = ref<Session[]>([]); const users = ref<User[]>([]); const invitations = ref<any[]>([]); const tags = ref<any[]>([]); const trash = ref<{ ideas: Idea[]; products: Product[] }>({ ideas: [], products: [] }); const status = ref<SystemStatus>(); const error = ref(''); const busy = ref(false); const inviteURL = ref(''); const resetURL = ref(''); const backupPath = ref('')
const tabs = [['profile','个人资料'],['devices','登录设备'],['admin','账号与邀请'],['tags','标签维护'],['trash','回收站'],['data','数据与系统']]
async function run(action: () => Promise<void>) { error.value = ''; busy.value = true; try { await action() } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
async function loadDevices() { sessions.value = (await api<{ items: Session[] }>('/sessions')).items }
async function loadAdmin() { const [userResult,inviteResult] = await Promise.all([api<{ items: User[] }>('/admin/users'),api<{ items: any[] }>('/admin/invitations')]); users.value = userResult.items; invitations.value = inviteResult.items }
async function loadTags() { tags.value = (await api<{ items: any[] }>('/tags')).items }
async function loadTrash() { trash.value = await api('/trash') }
async function loadStatus() { status.value = await api('/system/status') }
async function switchTab(value: string) { tab.value = value; error.value = ''; await run(async () => { if (value === 'devices') await loadDevices(); if (value === 'admin' && auth.user?.role === 'admin') await loadAdmin(); if (value === 'tags') await loadTags(); if (value === 'trash') await loadTrash(); if (value === 'data') await loadStatus() }) }
async function saveProfile() { await run(async () => { const result = await api<{ user: User }>('/auth/profile', { method: 'PATCH', body: JSON.stringify({ nickname: nickname.value }) }); auth.user = result.user; toast('昵称已更新') }) }
async function changePassword() { if (newPassword.value.length < 10) { error.value = '新密码至少 10 个字符'; return }; await run(async () => { await api('/auth/change-password', { method: 'POST', body: JSON.stringify({ current_password: currentPassword.value, new_password: newPassword.value, revoke_others: revokeOnPassword.value }) }); currentPassword.value = ''; newPassword.value = ''; toast('密码已修改') }) }
async function revoke(session: Session) { if (!confirm(session.current ? '撤销当前设备并退出登录？' : '撤销此设备的登录？')) return; await api(`/sessions/${session.id}`, { method: 'DELETE' }); if (session.current) { await clearAuth(true); router.push('/login') } else await loadDevices() }
async function revokeOthers() { if (!confirm('退出除当前设备外的所有设备？')) return; await api('/sessions/revoke-others', { method: 'POST' }); await loadDevices() }
async function invite() { await run(async () => { inviteURL.value = (await api<{ url: string }>('/admin/invitations', { method: 'POST' })).url; await loadAdmin() }) }
async function revokeInvite(id: string) { await api(`/admin/invitations/${id}`, { method: 'DELETE' }); await loadAdmin() }
async function toggleUser(user: User) { const next = user.status === 'active' ? 'disabled' : 'active'; if (!confirm(`${next === 'disabled' ? '停用' : '启用'}账号 ${user.username}？`)) return; await api(`/admin/users/${user.id}`, { method: 'PATCH', body: JSON.stringify({ status: next }) }); await loadAdmin() }
async function resetUser(user: User) { await run(async () => { resetURL.value = (await api<{ url: string }>('/admin/password-resets', { method: 'POST', body: JSON.stringify({ user_id: user.id }) })).url }) }
async function copy(value: string) { try { await navigator.clipboard.writeText(value); toast('链接已复制') } catch { prompt('请手动复制链接', value) } }
async function renameTag(item: any) { const name = prompt('新的标签名', item.name); if (!name || name === item.name) return; await api(`/tags/${item.id}`, { method: 'PATCH', body: JSON.stringify({ name }) }); await loadTags() }
async function deleteTag(item: any) { if (!confirm(`删除标签“${item.name}”？只会从灵感中移除标签，不删除灵感。`)) return; await api(`/tags/${item.id}`, { method: 'DELETE' }); await loadTags() }
async function restore(kind: 'ideas' | 'products', item: Idea | Product) { await api(`/${kind}/${item.id}/restore`, { method: 'POST', body: JSON.stringify({ version: item.version }) }); await loadTrash(); toast('已恢复') }
async function permanent(kind: 'ideas' | 'products', item: Idea | Product) { const name = kind === 'ideas' ? ideaTitle(item as Idea) : (item as Product).internal_name; if (!confirm(`永久删除“${name}”？此操作不可撤销，附件也会删除。关联的另一方内容不受影响。`)) return; await api(`/${kind}/${item.id}/permanent`, { method: 'DELETE', body: JSON.stringify({ version: item.version }) }); await loadTrash() }
async function backup() { await run(async () => { backupPath.value = (await api<{ path: string }>('/system/backup', { method: 'POST' })).path; toast('一致性备份已创建') }) }
onMounted(() => { loadStatus().catch(() => {}) })
</script>
<template><section><div class="page-heading"><div><h1>设置</h1><p>个人账号、共享内容与数据维护。</p></div></div><div class="settings-tabs"><button v-for="item in tabs" v-show="item[0] !== 'admin' || auth.user?.role === 'admin'" :key="item[0]" :class="{ active: tab === item[0] }" @click="switchTab(item[0])">{{ item[1] }}</button></div><p v-if="error" class="error-text">{{ error }}</p><div class="settings-section">
  <template v-if="tab === 'profile'"><form class="panel" @submit.prevent="saveProfile"><h2>个人资料</h2><div class="field"><label>用户名</label><input :value="auth.user?.username" disabled /></div><div class="field"><label for="nickname">显示昵称</label><input id="nickname" v-model="nickname" maxlength="80" required /></div><button class="primary" :disabled="busy">保存昵称</button></form><form class="panel" @submit.prevent="changePassword"><h2>修改密码</h2><div class="field"><label>当前密码</label><input v-model="currentPassword" type="password" autocomplete="current-password" required /></div><div class="field"><label>新密码</label><input v-model="newPassword" type="password" minlength="10" autocomplete="new-password" required /><small>至少 10 个字符。</small></div><label class="checkbox-label field"><input v-model="revokeOnPassword" type="checkbox" />同时退出其他所有设备</label><button class="primary" :disabled="busy">修改密码</button></form></template>
  <template v-else-if="tab === 'devices'"><section class="panel"><div class="page-heading"><div><h2>登录设备</h2><p>普通登录 7 天有效；记住设备最长 90 天。设备信息仅用于显示。</p></div><button class="secondary" @click="revokeOthers">退出其他设备</button></div><div v-for="session in sessions" :key="session.id" class="device-row"><div><strong>{{ session.device_name }} <span v-if="session.current" class="status-badge">当前设备</span></strong><small>最近活动 {{ formatDate(session.last_seen_at) }} · 到期 {{ formatDate(session.expires_at) }} · {{ session.remember ? '记住设备' : '普通登录' }}</small></div><button class="secondary small" @click="revoke(session)">撤销</button></div></section></template>
  <template v-else-if="tab === 'admin'"><section class="panel"><h2>邀请新用户</h2><p class="muted">一次性链接默认 24 小时有效，网站不开放自由注册。</p><button class="primary" :disabled="busy" @click="invite">创建一次性邀请链接</button><div v-if="inviteURL" class="field" style="margin-top:1rem"><label>新邀请链接</label><div class="link-add"><input :value="inviteURL" readonly /><button class="secondary" @click="copy(inviteURL)">复制</button></div></div><div v-for="item in invitations" :key="item.id" class="admin-row"><div><strong>{{ item.used_by || (item.used_at ? '已失效' : '待使用') }}</strong><small>创建 {{ formatDate(item.created_at) }} · 到期 {{ formatDate(item.expires_at) }}</small></div><button v-if="!item.used_at" class="secondary small" @click="revokeInvite(item.id)">撤销</button></div></section><section class="panel"><h2>账号管理</h2><div v-for="user in users" :key="user.id" class="admin-row"><div><strong>{{ user.nickname }}（{{ user.username }}）</strong><small>{{ user.role === 'admin' ? '管理员' : '成员' }} · {{ user.status === 'active' ? '正常' : '已停用' }}</small></div><button class="secondary small" @click="resetUser(user)">密码重置链接</button><button v-if="user.id !== auth.user?.id" class="secondary small" @click="toggleUser(user)">{{ user.status === 'active' ? '停用' : '启用' }}</button></div><div v-if="resetURL" class="field"><label>一次性密码重置链接（1 小时有效）</label><div class="link-add"><input :value="resetURL" readonly /><button class="secondary" @click="copy(resetURL)">复制</button></div></div></section></template>
  <template v-else-if="tab === 'tags'"><section class="panel"><h2>标签维护</h2><p class="muted">重命名或移除标签会同步更新灵感，不会删除灵感。</p><div v-for="item in tags" :key="item.id" class="tag-admin-row"><span class="tag">{{ item.name }}</span><span class="muted">{{ item.idea_count }} 条灵感</span><span style="flex:1"></span><button class="secondary small" @click="renameTag(item)">重命名</button><button class="text-button danger-text" @click="deleteTag(item)">删除</button></div><p v-if="!tags.length" class="muted">还没有标签。</p></section></template>
  <template v-else-if="tab === 'trash'"><section class="panel"><h2>回收站</h2><p class="muted">软删除的内容可以恢复。永久删除需要再次独立确认。</p><h3 v-if="trash.ideas.length">灵感</h3><div v-for="item in trash.ideas" :key="item.id" class="trash-row"><div><strong>{{ ideaTitle(item) }}</strong><small>删除于 {{ item.deleted_at ? formatDate(item.deleted_at) : '' }}</small></div><button class="secondary small" @click="restore('ideas',item)">恢复</button><button class="text-button danger-text" @click="permanent('ideas',item)">永久删除</button></div><h3 v-if="trash.products.length">商品</h3><div v-for="item in trash.products" :key="item.id" class="trash-row"><div><strong>{{ item.internal_name }}</strong><small>{{ statusLabels[item.development_status] }} · 删除于 {{ item.deleted_at ? formatDate(item.deleted_at) : '' }}</small></div><button class="secondary small" @click="restore('products',item)">恢复</button><button class="text-button danger-text" @click="permanent('products',item)">永久删除</button></div><p v-if="!trash.ideas.length && !trash.products.length" class="muted">回收站为空。</p></section></template>
  <template v-else><section class="panel"><h2>数据导出</h2><p class="muted">JSON 导出包含灵感、商品、动态属性和关联关系。附件原件包含在服务器备份归档中。</p><a class="primary" href="/api/export" download>导出 JSON</a></section><section class="panel"><h2>备份与恢复</h2><p class="muted">系统定期使用 SQLite 一致性备份生成数据库与附件归档，并自动清理旧备份。恢复时先停止服务，在服务器执行 bin/com-itemgather restore -archive 备份.tar.gz -yes。命令会校验归档并保留被替换的数据，详见 README。</p><template v-if="auth.user?.role === 'admin'"><button class="secondary" :disabled="busy" @click="backup">立即创建备份</button><p v-if="backupPath" class="backup-path">已创建：<span class="inline-code">{{ backupPath }}</span></p></template></section><section class="panel"><h2>系统状态</h2><template v-if="status"><p><strong>AI：</strong><span :class="status.ai.configured ? '' : 'error-text'">{{ status.ai.configured ? '已配置（密钥不会发送到浏览器）' : '未配置，文字仍会保存，整理任务会失败并可重试' }}</span></p><p><strong>模型：</strong><span class="inline-code">{{ status.ai.model }}</span> · 最多额外重试 {{ status.ai.max_retries }} 次 · Worker {{ status.ai.workers }}</p><p><strong>上传：</strong>单文件 {{ Math.round(status.upload.max_file_bytes / 1048576) }} MB，每条 {{ status.upload.max_attachments }} 张，总配额 {{ Math.round(status.upload.max_storage_bytes / 1048576) }} MB</p><p><strong>备份：</strong>{{ status.backup.interval }} 一次，保留 {{ status.backup.keep }} 份</p></template></section></template>
</div></section></template>
